//! The lines the two help screens print. Their texts are not in this source: each line is named by where the Linux
//! `soft` holds it (the pushes before each `fprintf` of `printUsage` and `usage`), and the text is read from the user's
//! own Softimage|3D 4.0 install when first used (`si-rt`, release model; `docs/design/runtime-data.md`). Unit rta held
//! all 89 lines against the literals this file carried before. Generated by `re/tools/si-app/gen_tables.py`; do not
//! edit by hand.

use std::sync::LazyLock;

/// The addresses in `soft` of the formats `printUsage (0x080cd10c)` prints with `fprintf(stderr, ...)`, in order.
pub const PRINT_USAGE_AT: [u32; 29] = [
    0x08679ea0, 0x08679ec0, 0x08679f00, 0x08679f35, 0x08679f50, 0x08679f69,
    0x08679f79, 0x08679fa0, 0x08679fdb, 0x08679fdd, 0x0867a000, 0x0867a040,
    0x0867a064, 0x0867a080, 0x0867a0c0, 0x0867a100, 0x0867a140, 0x0867a180,
    0x0867a1c0, 0x0867a200, 0x0867a240, 0x0867a280, 0x0867a2c0, 0x0867a2f2,
    0x0867a320, 0x0867a380, 0x0867a3c0, 0x0867a3fa, 0x0867a409,
];

/// The formats `printUsage (0x080cd10c)` prints with `fprintf(stderr, ...)`, in order, read once. The one with `%s`
/// takes the program's name.
pub static PRINT_USAGE: LazyLock<[&'static [u8]; 29]> = LazyLock::new(|| PRINT_USAGE_AT.map(si_rt::message));

