#[cfg(test)]
mod tests {
    use super::*;

    /// The lines as the original holds them: our checksums of the old literals (each line followed by a zero).
    #[test]
    fn the_lines_read_from_the_install() {
        si_rt::skip_without_install!();
        let flat = |l: &[&[u8]]| l.iter().flat_map(|t| t.iter().copied().chain([0])).collect::<Vec<u8>>();
        let b = flat(&PRINT_USAGE[..]);
        assert_eq!((b.len(), si_rt::fnv1a64(&b)), (1070, 0xdfc6_d8fa_a3d4_26e1));
        let b = flat(&RENDER_USAGE[..]);
        assert_eq!((b.len(), si_rt::fnv1a64(&b)), (3136, 0xd6b4_ac86_5603_fb18));
    }
}
